import "forge-std/Test.sol";
import "../src/timelock.sol";

contract TimeLockTest is Test {
    TimeLock timelock;
    address internal user = makeAddr("user");
    uint256 public constant MANIPULATION_DELAY = 300; // 5 minutes (300 seconds)

    function setUp() public {
        // Set safe initial timestamp (1000 seconds)
        vm.warp(1000);
        timelock = new TimeLock();
        vm.deal(user, 1 ether); // Fund user with 1 ETH
    }

    function testTimestampManipulation() public {
        uint256 baseTime = block.timestamp;
        uint256 initialUserBalance = address(user).balance;

        // Simulate miner manipulating timestamp backward by 5 minutes
        vm.warp(baseTime - MANIPULATION_DELAY);

        // Deposit in manipulated block
        vm.prank(user);
        timelock.deposit{value: 1 ether}();

        uint256 unlockTime = timelock.lockTime(user);
        uint256 expectedUnlock = block.timestamp + 1 weeks;

        // Verify lock time was manipulated to be 5 minutes earlier
        assertEq(unlockTime, expectedUnlock, "Lock time not reduced by manipulation");

        // Attempt withdrawal 1 second before unlock (should fail)
        vm.warp(unlockTime - 1);
        vm.prank(user);
        vm.expectRevert("Funds are still locked");
        timelock.withdraw();

        // Attempt withdrawal exactly at unlock time (should still fail)
        vm.warp(unlockTime);
        vm.prank(user);
        vm.expectRevert("Funds are still locked");
        timelock.withdraw();

        // Withdraw 1 second after unlock time (should succeed)
        vm.warp(unlockTime + 1);
        vm.prank(user);
        timelock.withdraw();

        // Verify funds moved correctly
        assertEq(address(timelock).balance, 0, "Contract funds not emptied");
        assertEq(address(user).balance, initialUserBalance, "User funds not restored");
    }
}
